    if (num(p.min_credit_score) !== null) credit.push(num(p.min_credit_score));
    if (num(p.min_age) !== null) age.push(num(p.min_age));
    if (num(p.max_age) !== null) age.push(num(p.max_age) + 1);  // age <= max  ⇔  age < max+1
